static int failures;

static void check_ok(const char *name, int cond)
{
    if (cond) printf("  PASS  %s\n", name);
    else { printf("  FAIL  %s\n", name); failures++; }
}

/* Decompress the whole of `gz` in one call, with generous buffers. */
static int gzip_whole(const uint8_t *gz, size_t gzlen, uint8_t *out, size_t outcap, size_t *outlen)
{
    gzip_ctx ctx;
    gzip_init(&ctx);
    size_t in_used, produced;
    int done = 0;
    int rc = gzip_feed(&ctx, gz, gzlen, out, outcap, &in_used, &produced, &done);
    *outlen = produced;
    if (rc != 0) return -1;
    if (in_used != gzlen) return -2;
    if (!done) return -3;
    return 0;
}

